from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.parsers.rtg_benchmark_parser import RtgBenchmarkParser


def add_benchmark_stats(log_dir):
    benchmark_stats = RtgBenchmarkParser(log_dir).get_rtg_benchmarks()
    for device, value in benchmark_stats['TTI Start Avg'].items():
        tc.add_stats(stats={'DB->decimal properties->device:{}->TTI Start Avg'.format(device): value})
    for device, value in benchmark_stats['TTI Length Avg'].items():
        tc.add_stats(stats={'DB->decimal properties->device:{}->TTI Length Avg'.format(device): value})
    for device in benchmark_stats['CPU Load']:
        for core, value in benchmark_stats['CPU Load'][device].items():
            tc.add_stats(stats={
                'DB->decimal properties->device:{}->core:{}->CPU load AVG'.format(device, core): value['AVG']})
            tc.add_stats(stats={
                'DB->decimal properties->device:{}->core:{}->CPU load MIN'.format(device, core): value['MIN']})
            tc.add_stats(stats={
                'DB->decimal properties->device:{}->core:{}->CPU load MAX'.format(device, core): value['MAX']})
